/**
 * ═══════════════════════════════════════════════════════════════════════════════
 * SERVICIO: Correo de resultado de evaluación + certificado
 * ═══════════════════════════════════════════════════════════════════════════════
 * Reusa el mismo transporte de Gmail que ya usa el OTP (email.service.js →
 * MAIL_USER / MAIL_PASS). Tablas y estilos en línea a propósito: los clientes
 * de correo (sobre todo Outlook) no soportan flexbox/grid ni CSS externo.
 *
 *   - Si aprobó  → correo con formato de certificado + el certificado también
 *                  va adjunto como archivo .html independiente (para guardar
 *                  o imprimir aparte del correo).
 *   - Si no aprobó → correo simple con el resultado, sin marco de certificado.
 *
 * Nunca lanza hacia el controlador: si el envío falla, se loguea y el intento
 * queda con correo_enviado = false para poder reintentar a mano.
 */

const { send } = require('./email.service');

const fechaLarga = (d) =>
  new Date(d).toLocaleDateString('es-EC', { day: 'numeric', month: 'long', year: 'numeric', timeZone: 'America/Guayaquil' });

// Fondo decorativo del certificado (pergamino + brújula), comprimido a JPG
// y embebido en base64: así el .html adjunto y el cuerpo del correo son
// 100% autocontenidos, sin depender de una URL externa que se pueda romper.
const FONDO_CERTIFICADO_B64 = '';

// Rubrica real subida por el administrador — fondo blanco removido y tinta
// tenida de navy para que combine con la paleta del certificado.
const FIRMA_CERTIFICADO_B64 = '';

function plantillaCertificado({ nombre, tituloEvaluacion, moduloTema, nota, fecha, empresa }) {
  return `<!DOCTYPE html>
<html lang="es">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:0;background:#eef1f5;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#eef1f5;padding:32px 12px;">
    <tr><td align="center">

      <table role="presentation" width="100%" cellpadding="0" cellspacing="0"
             style="max-width:680px;font-family:Arial,Helvetica,sans-serif;">
        <tr>
          <td style="background-color:#f4ecd8;background-image:url('data:image/jpeg;base64,${FONDO_CERTIFICADO_B64}');background-size:cover;background-position:center;background-repeat:no-repeat;border:1px solid #c9a227;border-radius:6px;padding:36px 44px;">

            <!-- Encabezado -->
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0">
              <tr>
                <td align="left" valign="middle">
                  <div style="font-size:16px;font-weight:bold;color:#0F2A4A;letter-spacing:.5px;">📈 ERP · ${(empresa || 'NOVONET/VELSA').toUpperCase()}</div>
                  <div style="font-size:10.5px;color:#8C6D1F;text-transform:uppercase;letter-spacing:1.5px;margin-top:2px;">Módulo de Evaluaciones</div>
                </td>
                <td align="right" valign="middle" style="font-size:30px;">🏆</td>
              </tr>
            </table>

            <!-- Cuerpo -->
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:18px;">
              <tr>
                <td align="center" style="padding:0 10px;">
                  <p style="margin:0 0 14px;font-family:Georgia,'Times New Roman',serif;font-size:25px;font-weight:bold;letter-spacing:2px;text-transform:uppercase;color:#8C6D1F;">
                    Certificado de Aprobación
                  </p>
                  <p style="margin:0 0 10px;font-size:13px;color:#64748B;">Se certifica que</p>
                  <p style="margin:0 0 16px;display:inline-block;border-bottom:2px solid #d9cbb0;padding-bottom:6px;font-size:22px;font-weight:bold;letter-spacing:.5px;text-transform:uppercase;color:#0F2A4A;">
                    ${nombre}
                  </p>
                  <p style="margin:0 0 4px;font-size:13.5px;color:#3f3f46;">aprobó satisfactoriamente la evaluación</p>
                  <p style="margin:0 0 20px;font-size:18px;font-weight:bold;color:#1e293b;">
                    ${tituloEvaluacion}${moduloTema ? ` <span style="font-weight:normal;color:#8a8a8a;">— ${moduloTema}</span>` : ''}
                  </p>

                  <table role="presentation" cellpadding="0" cellspacing="0" align="center" style="margin:0 auto 16px;">
                    <tr>
                      <td style="padding:10px 26px;background:#eafaf3;border:1px solid #9adfc0;border-radius:30px;text-align:center;">
                        <span style="display:block;font-size:10.5px;text-transform:uppercase;letter-spacing:.5px;color:#15803D;font-weight:600;">Calificación obtenida</span>
                        <span style="font-size:22px;color:#0f9d63;font-weight:bold;">${nota}%</span>
                      </td>
                    </tr>
                  </table>

                  <p style="margin:0 0 22px;font-size:12px;color:#6b6b6b;">${fechaLarga(fecha)}</p>
                </td>
              </tr>
            </table>

            <!-- Firma y sello -->
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:6px;">
              <tr>
                <td align="left" valign="bottom" width="55%">
                  <img src="data:image/png;base64,${FIRMA_CERTIFICADO_B64}" alt="Firma" width="150" style="display:block;margin-bottom:-6px;" />
                  <div style="border-top:1px solid #b9ab8a;margin-top:2px;padding-top:5px;font-size:11px;font-weight:600;color:#3f3f46;">Firma de Administrador</div>
                </td>
                <td align="right" valign="bottom" width="45%">
                  <table role="presentation" cellpadding="0" cellspacing="0" style="margin-left:auto;">
                    <tr>
                      <td style="width:64px;height:64px;border-radius:50%;border:2px dashed #15803D;text-align:center;vertical-align:middle;font-size:10px;color:#15803D;font-weight:bold;line-height:1.2;">
                        ✓<br/>VERIFICADO
                      </td>
                    </tr>
                  </table>
                  <div style="font-size:9.5px;color:#8a8a8a;margin-top:4px;">${fechaLarga(fecha)}</div>
                </td>
              </tr>
            </table>

            <!-- Aviso -->
            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-top:22px;">
              <tr>
                <td style="border-top:1px solid #d9cbb0;padding-top:12px;text-align:center;">
                  <p style="margin:0 0 4px;font-size:11px;color:#4b4b4b;">
                    ¡Felicitaciones! Este certificado también va adjunto como archivo aparte por si quieres guardarlo o imprimirlo.
                  </p>
                  <p style="margin:0;font-size:9.5px;color:#8a8a8a;line-height:1.4;">
                    Uso exclusivamente interno de ERP ${empresa || 'Novonet/Velsa'} — no tiene validez legal externa. Válido solo para registros internos del sistema.
                  </p>
                </td>
              </tr>
            </table>

          </td>
        </tr>
      </table>

    </td></tr>
  </table>
</body>
</html>`;
}
function plantillaResultado({ nombre, tituloEvaluacion, moduloTema, nota, notaMinima, fecha, empresa }) {
  return `<!DOCTYPE html>
<html lang="es">
<head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head>
<body style="margin:0;padding:0;background:#f1f5f9;">
  <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f1f5f9;padding:32px 12px;">
    <tr><td align="center">

      <table role="presentation" width="100%" cellpadding="0" cellspacing="0"
             style="max-width:480px;background:#ffffff;border-radius:16px;overflow:hidden;
                    box-shadow:0 4px 16px rgba(15,37,71,.08);font-family:Arial,Helvetica,sans-serif;">

        <tr>
          <td style="background:#1A3A6E;padding:26px 32px;text-align:center;">
            <div style="color:#ffffff;font-size:20px;font-weight:bold;letter-spacing:.5px;">ERP · ${empresa || 'Novonet / Velsa'}</div>
            <div style="color:#a5c3ee;font-size:11px;letter-spacing:2px;text-transform:uppercase;margin-top:4px;">
              Módulo de Evaluaciones
            </div>
          </td>
        </tr>

        <tr>
          <td style="padding:32px;">
            <p style="margin:0 0 6px;font-size:16px;color:#1e293b;font-weight:bold;">Hola, ${nombre}</p>
            <p style="margin:0 0 20px;font-size:13.5px;color:#64748b;line-height:1.6;">
              Este es el resultado de tu evaluación <strong>${tituloEvaluacion}</strong>${moduloTema ? ` (${moduloTema})` : ''}.
            </p>

            <table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin-bottom:20px;">
              <tr>
                <td style="padding:16px 18px;background:#fef2f2;border:1px solid #fca5a5;border-radius:10px;text-align:center;">
                  <span style="font-size:12px;color:#991b1b;font-weight:600;">Calificación obtenida</span><br/>
                  <span style="font-size:26px;color:#dc2626;font-weight:bold;">${nota}%</span><br/>
                  <span style="font-size:11px;color:#b91c1c;">Nota mínima para aprobar: ${notaMinima}%</span>
                </td>
              </tr>
            </table>

            <p style="margin:0;font-size:12.5px;color:#94a3b8;line-height:1.6;border-top:1px solid #e2e8f0;padding-top:16px;">
              No alcanzaste la nota mínima esta vez. Conversa con tu supervisor sobre los
              temas a reforzar. · ${fechaLarga(fecha)}
            </p>
          </td>
        </tr>

        <tr>
          <td style="background:#f8fafc;padding:14px 32px;text-align:center;border-top:1px solid #e2e8f0;">
            <p style="margin:0;font-size:11px;color:#94a3b8;">
              Mensaje automático del Sistema ERP · No respondas a este correo
            </p>
          </td>
        </tr>

      </table>

    </td></tr>
  </table>
</body>
</html>`;
}

/**
 * Envía el correo de resultado (y certificado adjunto si aprobó).
 * Nunca lanza: devuelve { ok, error? } para que el controlador decida si
 * marca correo_enviado = true sin tumbar la respuesta al usuario.
 */
async function enviarResultadoEvaluacion({
  correoDestino, nombre, tituloEvaluacion, moduloTema, nota, notaMinima, aprobado, fecha, empresa,
}) {
  if (!correoDestino) {
    console.warn('[evaluacionesCorreo] Usuario sin correo registrado — no se envía resultado');
    return { ok: false, error: 'El usuario no tiene correo registrado' };
  }

  try {
    const datos = { nombre, tituloEvaluacion, moduloTema, nota, notaMinima, fecha, empresa };

    if (aprobado) {
      const html = plantillaCertificado(datos);
      await send({
        to: correoDestino,
        subject: `🏆 ¡Aprobaste! Certificado — ${tituloEvaluacion}`,
        html,
        attachments: [{
          filename: `Certificado - ${tituloEvaluacion}.html`.replace(/[\\/:*?"<>|]/g, '_'),
          content: html,
          contentType: 'text/html',
        }],
      });
    } else {
      await send({
        to: correoDestino,
        subject: `Resultado de tu evaluación — ${tituloEvaluacion}`,
        html: plantillaResultado(datos),
      });
    }

    return { ok: true };
  } catch (error) {
    console.error('[evaluacionesCorreo] Error enviando resultado:', error.message);
    return { ok: false, error: error.message };
  }
}

module.exports = { enviarResultadoEvaluacion, plantillaCertificado, plantillaResultado };
